Source code in <code>src/ASTRA/Instruments/ESPRESSO.py</code> <pre><code>def check_header_QC_ESO_DRS(self, header):
    nonfatal_QC_flags = {
        "HIERARCH ESO INS5 ADC{} RA": 0,  # related with ADC2 problem
        "HIERARCH ESO INS5 ADC{} dec": 0,  # related with ADC2 problem
        "HIERARCH ESO INS5 ADC{} SENS1": 0,  # related with ADC2 problem
        "HIERARCH ESO INS5 ADC{} TEMP": 0,  # related with ADC2 problem
    }
    found_ADC_issue = False
    for flag, bad_value in nonfatal_QC_flags.items():
        found_UT = False
        try:
            for ADC in [1, 2]:
                ADC_KW = flag.format(self.UT_number, ADC)
                if header[ADC_KW] == bad_value:
                    msg = f"QC flag {ADC_KW} has a value of {bad_value}"
                    logger.warning(msg)
                    self._status.store_warning(KW_WARNING(msg))
                    found_ADC_issue = True
                found_UT = True
        except:
            pass
        if not found_UT:
            logger.critical(
                f"Did not find the entry for the following UT related metric: {flag}"
            )

    if found_ADC_issue:
        self._status.store_warning(KW_WARNING("ADC2 issues found"))

    super().check_header_QC_ESO_DRS(header)
